import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"56、【旅】 艮下离上","description":"横渠易说 - 56、【旅】 艮下离上","frontmatter":{"title":"56、【旅】 艮下离上","description":"横渠易说 - 56、【旅】 艮下离上"},"headers":[],"relativePath":"zh/classics/hengqu/058.md","filePath":"zh/classics/hengqu/058.md"}'),l={name:"zh/classics/hengqu/058.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_56、【旅】-艮下离上" tabindex="-1">56、【旅】 艮下离上 <a class="header-anchor" href="#_56、【旅】-艮下离上" aria-label="Permalink to “56、【旅】 艮下离上”">​</a></h1><h3 id="彖曰-旅小亨-柔得中乎外而顺乎刚-止而丽乎明-是以小亨旅贞吉也-旅之时义大矣哉" tabindex="-1">彖曰：“旅小亨”，柔得中乎外而顺乎刚，止而丽乎明，是以小亨旅贞吉也，旅之时义大矣哉! <a class="header-anchor" href="#彖曰-旅小亨-柔得中乎外而顺乎刚-止而丽乎明-是以小亨旅贞吉也-旅之时义大矣哉" aria-label="Permalink to “彖曰：“旅小亨”，柔得中乎外而顺乎刚，止而丽乎明，是以小亨旅贞吉也，旅之时义大矣哉!”">​</a></h3><h3 id="象曰-山上有火-旅-君子以明慎用刑而不留狱。" tabindex="-1">象曰：山上有火，旅，君子以明慎用刑而不留狱。 <a class="header-anchor" href="#象曰-山上有火-旅-君子以明慎用刑而不留狱。" aria-label="Permalink to “象曰：山上有火，旅，君子以明慎用刑而不留狱。”">​</a></h3><h3 id="初六-旅琐琐-斯其所取灾。-象曰-旅琐琐-志穷灾也。" tabindex="-1">初六，旅琐琐，斯其所取灾。 象曰：“旅琐琐”，志穷灾也。 <a class="header-anchor" href="#初六-旅琐琐-斯其所取灾。-象曰-旅琐琐-志穷灾也。" aria-label="Permalink to “初六，旅琐琐，斯其所取灾。 象曰：“旅琐琐”，志穷灾也。”">​</a></h3><p>琐琐，不能致命遂志，身穷而志卑也，冗细其所为，取灾之道也。</p><h3 id="六二-旅即次-怀其资-得童仆-贞。-象曰-得童仆贞-终无尤也。" tabindex="-1">六二，旅即次，怀其资，得童仆，贞。 象曰：“得童仆贞”，终无尤也。 <a class="header-anchor" href="#六二-旅即次-怀其资-得童仆-贞。-象曰-得童仆贞-终无尤也。" aria-label="Permalink to “六二，旅即次，怀其资，得童仆，贞。 象曰：“得童仆贞”，终无尤也。”">​</a></h3><p>居得位，即次之义，得三之助，故曰“怀其资”，下有一阴，无所系累，故曰“得童仆贞”。</p><h3 id="九三-旅焚其次-丧其童仆-贞厉。-象曰-旅焚其次-亦以伤矣-以旅与下-其义丧也。" tabindex="-1">九三，旅焚其次，丧其童仆，贞厉。 象曰：“旅焚其次”，亦以伤矣，以旅与下，其义丧也。 <a class="header-anchor" href="#九三-旅焚其次-丧其童仆-贞厉。-象曰-旅焚其次-亦以伤矣-以旅与下-其义丧也。" aria-label="Permalink to “九三，旅焚其次，丧其童仆，贞厉。 象曰：“旅焚其次”，亦以伤矣，以旅与下，其义丧也。”">​</a></h3><p>以阳居阳，其志亢也，旅而骄亢，焚次宜也。下比二阴，丧其御下之正，危厉之道。</p><h3 id="九四-旅于处-得其资斧-我心不快。-象曰-旅于处-未得位也。-得其资斧-心未快也。" tabindex="-1">九四，旅于处，得其资斧，我心不快。 象曰：“旅于处”，未得位也。“得其资斧”，心未快也。 <a class="header-anchor" href="#九四-旅于处-得其资斧-我心不快。-象曰-旅于处-未得位也。-得其资斧-心未快也。" aria-label="Permalink to “九四，旅于处，得其资斧，我心不快。 象曰：“旅于处”，未得位也。“得其资斧”，心未快也。”">​</a></h3><p>以阳居阴，旅于处也。所应在初，初为琐琐，志穷卑下，不能大助于己，但得其资斧之用而已，志未有得，故其心不快。</p><h3 id="六五-射雉一矢亡-终以誉命。-象曰-终以誉命-上逮也。" tabindex="-1">六五，射雉一矢亡，终以誉命。 象曰：“终以誉命”，上逮也。 <a class="header-anchor" href="#六五-射雉一矢亡-终以誉命。-象曰-终以誉命-上逮也。" aria-label="Permalink to “六五，射雉一矢亡，终以誉命。 象曰：“终以誉命”，上逮也。”">​</a></h3><p>四处阴应下，坚介难致，雉之象也，以力致之，徒丧其矢。丧矢，丧其直也，文明居中，必不失其直，当终得誉美。</p><h3 id="上九-鸟焚其巢-旅人先笑后号啕-丧牛于易-凶。-象曰-以旅在上-其义焚也-丧牛于易-终莫之闻也。" tabindex="-1">上九，鸟焚其巢，旅人先笑后号啕，丧牛于易，凶。 象曰：以旅在上，其义焚也；“丧牛于易”，终莫之闻也。 <a class="header-anchor" href="#上九-鸟焚其巢-旅人先笑后号啕-丧牛于易-凶。-象曰-以旅在上-其义焚也-丧牛于易-终莫之闻也。" aria-label="Permalink to “上九，鸟焚其巢，旅人先笑后号啕，丧牛于易，凶。 象曰：以旅在上，其义焚也；“丧牛于易”，终莫之闻也。”">​</a></h3><p>以阳极上，旅而骄肆者也，失柔顺之正，故曰“丧牛于易”。易，肆也，肆怒而忤物，虽有凶危，其谁告之，故曰“终莫之闻”也。</p>',15)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
